import type {LifeContext,RecurringMoment,MovementStyle,HardNo} from './life-map.ts';
import type {IllustrationCategory} from './illustrations.ts';

/**
 * The Opportunity Library: curated, structured movement opportunities that
 * live inside things people already do. This is the primary source of every
 * recommendation. AI may later reword a chosen opportunity; it never invents one.
 *
 * Copy rules for every entry:
 * - `descriptionTemplate` is CONDITIONAL ("Next time…", "If…") because the
 *   Life Map describes what tends to happen, not what is happening today.
 * - `action` is the direct form, used only when the person has just told us
 *   what is happening (Right now) or when the condition is already stated.
 * - `{minutes}` is the only placeholder.
 */
export type Intensity='very-light'|'light'|'moderate'|'vigorous';
export type LocationType='home'|'work'|'neighbourhood'|'shops'|'venue'|'park'|'transport'|'anywhere';
export type Assumption='garden'|'stairs'|'bike'|'washing-line';
export type MobilityRequirement='walking'|'walking-10'|'standing'|'stairs'|'carrying'|'floor';
export interface MovementOpportunity{
 id:string;
 /** Short moment label, e.g. "While they’re at sport". */
 title:string;
 /** Direct instruction, e.g. "Take a {minutes}-minute wander instead of waiting in the car." */
 action:string;
 /** Conditional, full-sentence framing for when Enough does not know it is happening. */
 descriptionTemplate:string;
 /** What the movement combines with, e.g. "a listening call". Empty only for standalone ideas. */
 pairsWith:string;
 contexts:LifeContext[];
 moments:RecurringMoment[];
 movementTypes:MovementStyle[];
 minMinutes:number;
 maxMinutes:number;
 /** Extra minutes taken from the day beyond what was already happening. */
 extraTimeMinutes:number;
 /** When true, the extra time equals the movement minutes (e.g. a lap before driving home). */
 extraScales:boolean;
 intensity:Intensity;
 locationTypes:LocationType[];
 requiresEquipment:boolean;
 requiresLeavingLocation:boolean;
 childCompatible:boolean;
 workCompatible:boolean;
 socialCompatible:boolean;
 mobilityRequirements:MobilityRequirement[];
 weatherDependent:boolean;
 /** Facilities the idea relies on; copy for these must stay conditional. */
 assumes:Assumption[];
 contraindicationTags:string[];
 /** Hard NOs this opportunity would violate. */
 hardConstraintTags:HardNo[];
 /** 1 (effortless) to 5 (a real ask). */
 burdenScore:number;
 /** 1 to 5: how much it also gets something done, saves money or connects people. */
 utilityScore:number;
 enjoymentTags:string[];
 imageCategory:IllustrationCategory;
 imageVariant?:string;
 evidenceLevel?:'everyday-walking'|'light-activity'|'sitting-breaks'|'active-transport'|'household-activity';
 /** Life contexts the person must have for this to make sense at all (no kids, no kids’ ideas). */
 requires:LifeContext[];
 /** True for ideas that fit almost any week (e.g. a walk after a meal). */
 universal:boolean;
 enabled:boolean;
}

type Seed=Pick<MovementOpportunity,'id'|'title'|'action'|'descriptionTemplate'|'contexts'|'moments'|'movementTypes'|'minMinutes'|'maxMinutes'|'imageCategory'>&Partial<MovementOpportunity>;
const evidenceFor=(s:Seed):MovementOpportunity['evidenceLevel']=>s.movementTypes.includes('useful')?'household-activity':s.movementTypes.includes('destination')?'active-transport':s.maxMinutes<=4?'sitting-breaks':'everyday-walking';
const requiredFor=(s:Seed):LifeContext[]=>s.id.startsWith('kids-')?['kids']:s.id.startsWith('pet-')?['pets']:s.id.startsWith('work-')?['desk']:[];
const o=(s:Seed):MovementOpportunity=>({requires:requiredFor(s),pairsWith:'',extraTimeMinutes:0,extraScales:false,intensity:'light',locationTypes:['neighbourhood'],requiresEquipment:false,requiresLeavingLocation:false,childCompatible:false,workCompatible:false,socialCompatible:false,mobilityRequirements:['walking'],weatherDependent:false,assumes:[],contraindicationTags:[],hardConstraintTags:[],burdenScore:2,utilityScore:2,enjoymentTags:[],universal:false,enabled:true,evidenceLevel:evidenceFor(s),...s});

