export const opportunityById=(id:string)=>opportunities.find(o=>o.id===id);
export const fillMinutes=(template:string,minutes:number)=>template.replaceAll('{minutes}',String(minutes));
/** Extra minutes from the day for a given duration. */
export const extraFor=(o:MovementOpportunity,minutes:number)=>o.extraScales?minutes:o.extraTimeMinutes;
